'use client';
import {
  useCallback, useEffect, useId, useImperativeHandle, useMemo, useRef, useState,
  type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode, type Ref, type RefObject,
} from 'react';
import { useStudioMotion } from '../../motion';
import { StudioCanvas } from '../../three';
import type { EffectProps } from '../../types';
import { canvasMeasure, compose, compositionFonts, drawComposition, mix, readTheme, type Theme } from './composition';
import { LensEngine, SHAPE_IDS, type ShapeId } from './engine';
import { GlassFallback, PageSvg } from './fallback';
import { Scene, type GlassLook } from './scene';
import styles from './styles.module.css';

export type { ShapeId } from './engine';

/** Bumps when the document theme changes (class / data-theme / style on <html>, or the OS colour scheme). */
function useThemeVersion(): number {
  const [v, setV] = useState(0);
  useEffect(() => {
    const bump = () => setV((n) => n + 1);
    const mo = new MutationObserver(bump);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'class', 'style'] });
    const mq = window.matchMedia?.('(prefers-color-scheme: dark)');
    mq?.addEventListener('change', bump);
    return () => { mo.disconnect(); mq?.removeEventListener('change', bump); };
  }, []);
  return v;
}

function glassLook(t: Theme): GlassLook {
  const p = t.palette;
  // A bright studio for the light page, a dim one for the dark page: the glass reflects ~4% of it face-on, so the
  // ceiling colour sets how much the body veils what is under it.
  return p.dark
    ? { dark: true, envLo: mix(p.paper, '#ffffff', 0.04), envHi: mix(p.paper, '#ffffff', 0.22), light: '#fff7ec', shadow: '#000000', shadowAmount: 0.62, caustic: 1.5 }
    : { dark: false, envLo: mix(p.paper, p.ink, 0.5), envHi: mix(p.paper, p.ink, 0.34), light: '#fffaf2', shadow: '#4d5160', shadowAmount: 0.34, caustic: 0.14 };
}

export interface LensHandle {
  /** Glide the lens back to the centre of the stage. */
  recentre(): void;
}

export interface LiquidGlassLensProps {
  shape: ShapeId;
  /** 0 flat glass … 1.5 heavy bend at the rim. */
  refraction: number;
  /** 0 none … 1 strong colour split at the rim. */
  dispersion: number;
  /** 0 clear … 1 frosted. */
  frost: number;
  /** The highlight and shadow follow the pointer; off keeps the resting upper-left light. */
  followLight: boolean;
  /** Draws the page under the glass in CSS pixels (the context is pre-scaled to the drawing buffer). */
  draw: (g: CanvasRenderingContext2D, width: number, height: number) => void;
  /** Change it to redraw the page texture (theme, fonts or content changed). */
  drawKey: unknown;
  /** The same page as DOM/SVG, shown under a CSS glass panel when WebGL is unavailable. */
  fallback: ReactNode;
  /** Accessible name of the scene; the lens itself is named "Glass lens". */
  label: string;
  description?: string;
  /** Id of visible instructions for the lens; without it the component renders its own (visually hidden). */
  describedBy?: string;
  className?: string;
  ref?: Ref<LensHandle>;
}

/**
 * A draggable liquid-glass lens over any page you can draw: WebGL refraction, dispersion, frost and one moving light,
 * with a CSS glass fallback. The lens is a keyboard control too (arrows, Shift+arrows, Home).
 */
export function LiquidGlassLens({
  shape, refraction, dispersion, frost, followLight, draw, drawKey, fallback, label, description, describedBy, className, ref,
}: LiquidGlassLensProps) {
  const { reduced } = useStudioMotion();
  const ownHint = useId();
  const frame = useRef<HTMLDivElement>(null);
  const handle = useRef<HTMLDivElement>(null);
  const [engine] = useState(() => new LensEngine());
  const wake = useRef<(() => void) | null>(null);
  const onFrame = useRef<(() => void) | null>(null);
  const drawRef = useRef(draw);
  drawRef.current = draw;
  const [cssGlass, setCssGlass] = useState(false);
  const [message, setMessage] = useState('');
  const [look, setLook] = useState<GlassLook>(() => ({ dark: false, envLo: '#8a8780', envHi: '#e0ddd6', light: '#fffaf2', shadow: '#4d5160', shadowAmount: 0.34, caustic: 0.14 }));
  const themeVersion = useThemeVersion();
  const kick = useCallback(() => wake.current?.(), []);

  useEffect(() => { if (frame.current) setLook(glassLook(readTheme(frame.current))); }, [themeVersion]);
  useEffect(() => { engine.reduced = reduced; engine.follow = followLight; kick(); }, [engine, reduced, followLight, kick]);
  const first = useRef(true);
  useEffect(() => { engine.setShape(shape, first.current); first.current = false; kick(); }, [engine, shape, kick]);

  // DOM overlay (focus ring, hit area, CSS glass) follows the lens in the same frame as the canvas, and the frame's
  // own shadow takes the scene's light direction. Writes are skipped when nothing visible changed.
  const last = useRef('');
  const sync = useCallback(() => {
    const el = handle.current, fr = frame.current;
    if (!el || !fr) return;
    const f = engine.frame();
    const corner = f.r * (1 - 0.44 * Math.min(1, Math.max(0, (f.n - 2) / 2.4))); // superellipse ≈ smaller CSS radius
    const key = [f.x, f.y, f.hx, f.hy, corner, f.lx, f.ly, f.lift].map((v) => v.toFixed(2)).join();
    if (key === last.current) return;
    last.current = key;
    el.style.width = `${(2 * f.hx).toFixed(2)}px`;
    el.style.height = `${(2 * f.hy).toFixed(2)}px`;
    el.style.borderRadius = `${corner.toFixed(2)}px`;
    el.style.transform = `translate3d(${(f.x - f.hx).toFixed(2)}px, ${(f.y - f.hy).toFixed(2)}px, 0)`;
    fr.style.setProperty('--lx', f.lx.toFixed(3));
    fr.style.setProperty('--ly', f.ly.toFixed(3));
    fr.style.setProperty('--lift', f.lift.toFixed(3));
  }, [engine]);
  useEffect(() => { onFrame.current = sync; return () => { if (onFrame.current === sync) onFrame.current = null; }; }, [sync]);

  useEffect(() => {
    const el = frame.current;
    if (!el) return;
    const fit = () => { engine.setSize(el.clientWidth, el.clientHeight); onFrame.current?.(); kick(); };
    fit();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(fit);
    ro.observe(el);
    return () => ro.disconnect();
  }, [engine, kick]);

  // Spoken position after keyboard moves, debounced so held keys do not flood the live region.
  const announceTimer = useRef(0);
  const announce = useCallback((text?: string) => {
    window.clearTimeout(announceTimer.current);
    announceTimer.current = window.setTimeout(() => {
      const { fx, fy } = engine.where();
      setMessage(text ?? `Lens at ${Math.round(fx * 100)}% across, ${Math.round(fy * 100)}% down.`);
    }, 420);
  }, [engine]);
  useEffect(() => () => window.clearTimeout(announceTimer.current), []);

  useImperativeHandle(ref, () => ({ recentre: () => { engine.recentre(); kick(); announce('Lens centred.'); } }), [engine, kick, announce]);

  const local = (e: { clientX: number; clientY: number }) => {
    const r = frame.current!.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const onFramePointerMove = (e: PointerEvent<HTMLDivElement>) => { const p = local(e); engine.pointerMove(p.x, p.y, true); kick(); };
  const onFramePointerLeave = () => { if (!engine.dragging) { engine.pointerLeave(); kick(); } };
  const onFrameClick = (e: MouseEvent<HTMLDivElement>) => {
    if (handle.current?.contains(e.target as Node)) return;
    const p = local(e);
    engine.placeAt(p.x, p.y);
    kick();
  };
  const onHandleDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    const p = local(e);
    engine.dragStart(p.x, p.y);
    kick();
  };
  const onHandleUp = (e: PointerEvent<HTMLDivElement>) => {
    if (!engine.dragging) return;
    engine.dragEnd();
    if (e.pointerType !== 'mouse') engine.pointerLeave();
    kick();
  };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    const step = e.shiftKey ? 64 : 16;
    const moves: Record<string, [number, number]> = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
    if (moves[e.key]) { engine.nudge(...moves[e.key]); announce(); }
    else if (e.key === 'Home') { engine.recentre(); announce('Lens centred.'); }
    else return;
    e.preventDefault();
    kick();
  };

  const onActive = useCallback((on: boolean) => setCssGlass(on), []);
  const glassVars = { '--frost': frost.toFixed(3), '--refract': refraction.toFixed(3), '--disperse': dispersion.toFixed(3) } as Record<string, string>;

  return (
    <div
      ref={frame}
      className={`${styles.frame}${className ? ` ${className}` : ''}`}
      style={glassVars}
      data-css-glass={cssGlass || undefined}
      data-dark={look.dark || undefined}
      onPointerMove={onFramePointerMove}
      onPointerLeave={onFramePointerLeave}
      onClick={onFrameClick}
    >
      <StudioCanvas
        label={label}
        description={description}
        fallback={<GlassFallback engine={engine} wake={wake} onFrame={onFrame} onActive={onActive}>{fallback}</GlassFallback>}
      >
        <Scene engine={engine} draw={drawRef} drawKey={drawKey} refraction={refraction} dispersion={dispersion} frost={frost} look={look} wake={wake} onFrame={onFrame} />
      </StudioCanvas>
      <div
        ref={handle}
        className={styles.lens}
        role="application"
        aria-roledescription="movable lens"
        aria-label="Glass lens"
        aria-describedby={describedBy ?? ownHint}
        aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight Shift+ArrowUp Shift+ArrowDown Shift+ArrowLeft Shift+ArrowRight Home"
        tabIndex={0}
        onPointerDown={onHandleDown}
        onPointerUp={onHandleUp}
        onPointerCancel={onHandleUp}
        onLostPointerCapture={onHandleUp}
        onPointerEnter={(e) => { if (e.pointerType === 'mouse') { engine.setHover(true); kick(); } }}
        onPointerLeave={(e) => { if (e.pointerType === 'mouse') { engine.setHover(false); kick(); } }}
        onKeyDown={onKeyDown}
      />
      {describedBy ? null : (
        <p id={ownHint} className={styles.srOnly}>
          {reduced ? 'Drag the lens to move it.' : 'Drag the lens, or throw it.'} Arrow keys move it, Shift with an arrow moves it further, Home centres it.
        </p>
      )}
      <p className={styles.srOnly} role="status">{message}</p>
    </div>
  );
}

type Params = { refraction: number; dispersion: number; frost: number; shape: string; light: boolean };
const isShape = (v: string): v is ShapeId => (SHAPE_IDS as readonly string[]).includes(v);
const SHAPE_LABEL: Record<ShapeId, string> = { pill: 'Pill', circle: 'Circle', squircle: 'Squircle' };
const SHAPE_ICON: Record<ShapeId, string> = {
  pill: 'M5 6.5h8a3.5 3.5 0 010 7H5a3.5 3.5 0 010-7z',
  circle: 'M9 4.5a5.5 5.5 0 110 11 5.5 5.5 0 010-11z',
  squircle: 'M9 4.2c4.3 0 5 .7 5 5.8s-.7 5.8-5 5.8-5-.7-5-5.8.7-5.8 5-5.8z',
};

/**
 * Theme tokens for the sample page, re-read on theme changes and again once the page fonts have loaded. The theme and
 * its version change in the same update, so a redraw keyed on `version` always sees the matching theme.
 */
function usePageTheme(root: RefObject<HTMLElement | null>): { theme: Theme | null; version: number } {
  const themeVersion = useThemeVersion();
  const [state, setState] = useState<{ theme: Theme | null; version: number }>({ theme: null, version: 0 });
  useEffect(() => {
    if (!root.current) return;
    const theme = readTheme(root.current);
    setState((s) => ({ theme, version: s.version + 1 }));
    let alive = true;
    if (document.fonts?.load) {
      Promise.all(compositionFonts(theme.fonts).map((f) => document.fonts.load(f).catch(() => []))).then(() => {
        if (alive) setState((s) => ({ ...s, version: s.version + 1 }));
      });
    }
    return () => { alive = false; };
  }, [root, themeVersion]);
  return state;
}

export default function LiquidGlassLensRecipe({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const hintId = useId();
  const root = useRef<HTMLDivElement>(null);
  const lens = useRef<LensHandle>(null);
  const [shape, setShape] = useState<ShapeId>(isShape(params.shape) ? params.shape : 'pill');
  useEffect(() => { if (isShape(params.shape)) setShape(params.shape); }, [params.shape]);
  const { theme, version } = usePageTheme(root);

  const draw = useCallback((g: CanvasRenderingContext2D, w: number, h: number) => {
    if (theme) drawComposition(g, w, h, compose(w / h, theme, canvasMeasure()));
  }, [theme]);
  const fallback = useMemo(() => <PageSvg theme={theme} />, [theme]);

  return (
    <div ref={root} className={styles.root}>
      <LiquidGlassLens
        ref={lens}
        shape={shape}
        refraction={params.refraction}
        dispersion={params.dispersion}
        frost={params.frost}
        followLight={params.light}
        draw={draw}
        drawKey={version}
        fallback={fallback}
        label="Glass lens over a sample magazine page"
        description="A thick glass lens rests on a typographic proof sheet: a large word, a red sun striped with bars, columns of small text, a colour bar and print marks. Through its flat centre the page is unchanged; around its rim the page bends, splits into colour and catches the light."
        describedBy={hintId}
      />
      <div className={styles.toolbar}>
        <div role="group" aria-label="Lens shape" className={styles.shapes}>
          {SHAPE_IDS.map((id) => (
            <button key={id} type="button" className={styles.shape} aria-pressed={shape === id} onClick={() => setShape(id)}>
              <svg viewBox="0 0 18 20" aria-hidden="true" focusable="false"><path d={SHAPE_ICON[id]} /></svg>
              {SHAPE_LABEL[id]}
            </button>
          ))}
        </div>
        <button type="button" className={styles.centre} onClick={() => lens.current?.recentre()}>
          <svg viewBox="0 0 18 18" aria-hidden="true" focusable="false"><circle cx="9" cy="9" r="3.2" /><path d="M9 1.5v3.2M9 13.3v3.2M1.5 9h3.2M13.3 9h3.2" /></svg>
          Centre
        </button>
        <p id={hintId} className={styles.hint}>
          {reduced
            ? 'Reduced motion: the lens follows your hand directly and the light stays fixed.'
            : 'Drag or throw the lens, or click the page to send it there.'}{' '}
          <span className={styles.keys}>Arrows move it · Shift for bigger steps · Home centres.</span>
        </p>
      </div>
    </div>
  );
}

/**
 * The sample backdrop: a proof sheet for a fictional optics quarterly, laid out once in design units and rendered
 * twice from the same items — with canvas2d into the lens texture, and as SVG for the no-WebGL fallback — in the
 * current theme's tokens. Large type, colour fields, hairline grid and print marks give the glass something to bend.
 */

export interface Palette {
  paper: string; paper2: string; ink: string; muted: string; line: string;
  signal: string; onSignal: string; blue: string; green: string; ochre: string; magenta: string;
  /** The surface is dark (dark theme or an always-dark stage). */
  dark: boolean;
}
export interface Fonts { display: string; text: string; serif: string; mono: string }
export interface Theme { palette: Palette; fonts: Fonts }

type Rgba = [number, number, number, number];
let probe: CanvasRenderingContext2D | null | undefined;
const ctx2d = () => (probe === undefined ? (probe = document.createElement('canvas').getContext('2d')) : probe);

/** Any CSS colour → [r, g, b, a] (0–255, alpha 0–1), normalised by the browser's own parser. */
export function toRgba(css: string): Rgba {
  const g = ctx2d();
  if (!g) return [0, 0, 0, 1];
  g.fillStyle = '#000';
  g.fillStyle = css;
  const v = String(g.fillStyle);
  if (v.startsWith('#')) return [parseInt(v.slice(1, 3), 16), parseInt(v.slice(3, 5), 16), parseInt(v.slice(5, 7), 16), 1];
  const m = v.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0, 1];
  return [m[0], m[1], m[2], m[3] ?? 1];
}
const hex = ([r, g, b]: Rgba) => `#${[r, g, b].map((c) => Math.round(Math.min(255, Math.max(0, c))).toString(16).padStart(2, '0')).join('')}`;
/** `a` mixed toward `b` by t, as an opaque hex colour. */
export const mix = (a: string, b: string, t: number): string => {
  const x = toRgba(a), y = toRgba(b);
  return hex([x[0] + (y[0] - x[0]) * t, x[1] + (y[1] - x[1]) * t, x[2] + (y[2] - x[2]) * t, 1]);
};
/** WCAG relative luminance of a CSS colour. */
export function luminance(css: string): number {
  const [r, g, b] = toRgba(css);
  const lin = (c: number) => { const s = c / 255; return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}

/** Theme tokens as resolved on `el` (inherits the gallery or app theme), with the contract's fallbacks. */
export function readTheme(el: Element): Theme {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  const paper = v('--mk-surface', '#fbf9f4');
  return {
    palette: {
      paper, paper2: v('--mk-surface-2', '#e9e5da'), ink: v('--mk-ink', '#11110f'), muted: v('--mk-ink-muted', '#5c5a52'),
      line: v('--mk-line', '#11110f24'), signal: v('--mk-signal', '#bf2f09'), onSignal: v('--mk-on-signal', '#ffffff'),
      blue: v('--mk-accent-product', '#2446d8'), green: v('--mk-accent-data', '#0a6e4d'), ochre: v('--mk-accent-3d', '#8a5a00'),
      magenta: v('--mk-accent-social', '#b8166f'), dark: luminance(paper) < 0.2,
    },
    fonts: {
      display: v('--mk-font-display', 'ui-sans-serif, system-ui, sans-serif'), text: v('--mk-font-text', 'ui-sans-serif, system-ui, sans-serif'),
      serif: v('--mk-font-serif', 'Georgia, serif'), mono: v('--mk-font-mono', 'ui-monospace, monospace'),
    },
  };
}

/** Faces the composition uses; resolve them before drawing so the texture never bakes a fallback font. */
export const compositionFonts = (f: Fonts): string[] => [`800 100px ${f.display}`, `italic 400 100px ${f.serif}`, `500 20px ${f.mono}`, `400 20px ${f.text}`];

export type Align = 'left' | 'center' | 'right';
export interface TextItem {
  k: 'text'; x: number; y: number; text: string; family: string; size: number; weight: number;
  italic?: boolean; /** em */ tracking: number; fill: string; align: Align;
}
export type Item =
  | { k: 'rect'; x: number; y: number; w: number; h: number; fill: string }
  | { k: 'grid'; w: number; h: number; step: number; every: number; minor: string; major: string }
  | { k: 'line'; x1: number; y1: number; x2: number; y2: number; stroke: string; width: number }
  | { k: 'reg'; cx: number; cy: number; r: number; stroke: string }
  /** A disc with horizontal bars knocked out of its lower half. */
  | { k: 'sun'; cx: number; cy: number; r: number; fill: string; bars: readonly [number, number][]; barFill: string }
  /** Halftone ramp: dots growing left → right. */
  | { k: 'dots'; x: number; y: number; w: number; h: number; step: number; r0: number; r1: number; fill: string }
  | TextItem;
export interface Composition { width: number; height: number; items: readonly Item[] }

/** Font shorthand for canvas and measuring. */
export const fontOf = (t: Pick<TextItem, 'family' | 'size' | 'weight' | 'italic'>) => `${t.italic ? 'italic ' : ''}${t.weight} ${t.size}px ${t.family}`;

export interface Measure { width(text: string, font: string): number; capHeight(font: string): number }
export function canvasMeasure(): Measure {
  return {
    width: (text, font) => { const g = ctx2d(); if (!g) return text.length * 10; g.font = font; return g.measureText(text).width; },
    capHeight: (font) => { const g = ctx2d(); if (!g) return 70; g.font = font; return g.measureText('H').actualBoundingBoxAscent || 70; },
  };
}

const HEADLINE = ['Light, bent', 'through thick glass.'];
const BODY = [
  'A thick lens bends whatever it crosses. Where the surface curves, light slows, turns and opens into its colours; over the flat centre it passes almost untouched.',
  'Read the page through it: the rim gathers rules, type and colour into one bright edge, while the shadow falls away from the light, softer the higher the glass is held.',
];

/** Greedy word wrap with the real font metrics. */
function wrap(text: string, font: string, width: number, m: Measure): string[] {
  const out: string[] = [];
  let line = '';
  for (const word of text.split(' ')) {
    const next = line ? `${line} ${word}` : word;
    if (line && m.width(next, font) > width) { out.push(line); line = word; } else line = next;
  }
  if (line) out.push(line);
  return out;
}

/** Largest size at which `text` fits `width` (tracking included), capped at `max`. */
function fit(text: string, family: string, weight: number, tracking: number, width: number, max: number, m: Measure): number {
  const ref = 100;
  const w = m.width(text, `${weight} ${ref}px ${family}`) + tracking * ref * (text.length - 1);
  return Math.min(max, (width / Math.max(1, w)) * ref);
}

/**
 * Lay out the proof sheet for a stage of the given aspect ratio (width / height): a landscape spread, or a portrait
 * page below 1. Everything is in design units; renderers scale the result to cover the stage.
 */
export function compose(aspect: number, { palette: p, fonts: f }: Theme, m: Measure): Composition {
  const portrait = aspect < 1.02;
  const W = portrait ? 400 : 1000;
  const H = portrait ? 500 : 562;
  const M = portrait ? 22 : 40;
  const items: Item[] = [];
  const text = (t: Omit<TextItem, 'k'>) => items.push({ k: 'text', ...t });
  const mono = (s: string, x: number, y: number, align: Align, fill = p.muted, size = portrait ? 8.5 : 10) =>
    text({ x, y, text: s.toUpperCase(), family: f.mono, size, weight: 500, tracking: 0.12, fill, align });

  items.push({ k: 'rect', x: 0, y: 0, w: W, h: H, fill: p.paper });
  items.push({ k: 'grid', w: W, h: H, step: portrait ? 25 : 40, every: 4, minor: mix(p.paper, p.ink, p.dark ? 0.09 : 0.06), major: mix(p.paper, p.ink, p.dark ? 0.17 : 0.13) });

  // Masthead and its rule.
  const top = portrait ? 30 : 34;
  mono('Optics & Matter', M + 14, top, 'left', p.ink);
  if (!portrait) mono('Nº 07 — The light issue', W / 2, top, 'center');
  mono('Sample composition', W - M - 14, top, 'right');
  items.push({ k: 'line', x1: M, y1: top + 12, x2: W - M, y2: top + 12, stroke: p.ink, width: 1 });

  // Colour field: the sun, with bars knocked out of its lower half.
  const sun = portrait ? { cx: 300, cy: 142, r: 78 } : { cx: 772, cy: 198, r: 134 };
  const bars: [number, number][] = [];
  for (let k = 0, y = sun.cy + sun.r * 0.12; k < 7 && y < sun.cy + sun.r; k++) {
    const h = sun.r * (0.018 + k * 0.014);
    bars.push([y, h]);
    y += h + sun.r * (0.115 - k * 0.006);
  }
  items.push({ k: 'sun', ...sun, fill: p.signal, bars, barFill: p.paper });
  mono(portrait ? 'Fig. 1 — n = 1.52' : 'Fig. 1 — one light, one lens, n = 1.52', sun.cx + sun.r, sun.cy + sun.r + (portrait ? 16 : 22), 'right');

  // Headline in the serif italic, then two narrow columns of body copy.
  const hSize = portrait ? 34 : 54;
  const hLines = portrait ? ['Light,', 'bent through', 'thick glass.'] : HEADLINE;
  const hTop = portrait ? 92 : 124;
  hLines.forEach((s, i) => text({ x: M, y: hTop + i * hSize * (portrait ? 1.02 : 1.0), text: s, family: f.serif, size: hSize, weight: 400, italic: true, tracking: -0.01, fill: p.ink, align: 'left' }));

  const bSize = portrait ? 10.5 : 12;
  const bLead = bSize * 1.45;
  const bFont = `400 ${bSize}px ${f.text}`;
  const bTop = portrait ? 264 : 248;
  const cols = portrait ? [{ x: M, w: W - 2 * M, s: BODY[0] }] : [{ x: M, w: 212, s: BODY[0] }, { x: M + 236, w: 212, s: BODY[1] }];
  for (const c of cols) wrap(c.s, bFont, c.w, m).slice(0, portrait ? 4 : 6).forEach((s, i) => text({ x: c.x, y: bTop + i * bLead, text: s, family: f.text, size: bSize, weight: 400, tracking: 0, fill: p.muted, align: 'left' }));

  // The display word: as wide as the measure allows while its caps stay clear of the sun.
  const word = 'Refract';
  const baseline = portrait ? 428 : 498;
  const room = baseline - (portrait ? bTop + 4 * bLead + 4 : sun.cy + sun.r + 34);
  const capRatio = m.capHeight(`800 100px ${f.display}`) / 100;
  const dSize = fit(word, f.display, 800, -0.045, W - 2 * M, room / Math.max(0.5, capRatio), m);
  text({ x: M - dSize * 0.02, y: baseline, text: word, family: f.display, size: dSize, weight: 800, tracking: -0.045, fill: p.ink, align: 'left' });

  // Print furniture: colour bar of theme tokens, halftone ramp, ruler, registration marks.
  const barY = portrait ? 448 : 520;
  const sw = portrait ? 22 : 30, sh = portrait ? 12 : 14;
  const swatches = [p.ink, mix(p.ink, p.paper, 0.4), mix(p.ink, p.paper, 0.72), p.signal, mix(p.signal, p.paper, 0.5), p.blue, p.green, p.ochre, p.magenta, p.paper2];
  swatches.forEach((fill, i) => items.push({ k: 'rect', x: M + i * sw, y: barY, w: sw - 2, h: sh, fill }));
  const afterBar = M + swatches.length * sw + (portrait ? 10 : 18);
  items.push({ k: 'dots', x: afterBar, y: barY, w: portrait ? W - M - afterBar : 150, h: sh, step: portrait ? 5 : 6, r0: 0.35, r1: portrait ? 2.3 : 2.8, fill: p.ink });
  if (!portrait) {
    const rx = afterBar + 168, rw = W - M - rx;
    items.push({ k: 'line', x1: rx, y1: barY + sh, x2: rx + rw, y2: barY + sh, stroke: p.ink, width: 1 });
    for (let x = 0, i = 0; x <= rw + 0.01; x += 5, i++) items.push({ k: 'line', x1: rx + x, y1: barY + sh, x2: rx + x, y2: barY + sh - (i % 10 === 0 ? 14 : i % 2 === 0 ? 8 : 4), stroke: p.ink, width: 1 });
    for (let x = 0, n = 0; x <= rw + 0.01; x += 50, n++) mono(String(n), rx + x + 3, barY + 6, 'left', p.muted, 8);
  }
  mono(portrait ? 'Theme tokens' : 'Colour bar · theme tokens', M, barY + sh + (portrait ? 15 : 18), 'left');
  const reg = portrait ? 12 : 16;
  for (const [cx, cy] of [[reg, reg], [W - reg, reg], [reg, H - reg], [W - reg, H - reg]]) items.push({ k: 'reg', cx, cy, r: portrait ? 4.5 : 6, stroke: p.ink });

  return { width: W, height: H, items };
}

/** Cover-fit transform from design units to a stage of cssW × cssH (centred, like SVG `xMidYMid slice`). */
export function coverTransform(cssW: number, cssH: number, c: Composition) {
  const s = Math.max(cssW / c.width, cssH / c.height);
  return { s, ox: (cssW - c.width * s) / 2, oy: (cssH - c.height * s) / 2 };
}

/** Draw the composition with canvas2d, covering a cssW × cssH area (the caller sets any device-pixel scale first). */
export function drawComposition(g: CanvasRenderingContext2D, cssW: number, cssH: number, c: Composition): void {
  const { s, ox, oy } = coverTransform(cssW, cssH, c);
  g.save();
  g.transform(s, 0, 0, s, ox, oy);
  const tracked = 'letterSpacing' in g;
  for (const it of c.items) {
    switch (it.k) {
      case 'rect': g.fillStyle = it.fill; g.fillRect(it.x, it.y, it.w, it.h); break;
      case 'grid': {
        const hair = 1 / s; // one device-independent pixel, whatever the scale
        for (let i = 0, x = 0; x <= it.w; x += it.step, i++) { g.fillStyle = i % it.every ? it.minor : it.major; g.fillRect(x - hair / 2, 0, hair, it.h); }
        for (let i = 0, y = 0; y <= it.h; y += it.step, i++) { g.fillStyle = i % it.every ? it.minor : it.major; g.fillRect(0, y - hair / 2, it.w, hair); }
        break;
      }
      case 'line': g.strokeStyle = it.stroke; g.lineWidth = it.width; g.beginPath(); g.moveTo(it.x1, it.y1); g.lineTo(it.x2, it.y2); g.stroke(); break;
      case 'reg':
        g.strokeStyle = it.stroke; g.lineWidth = 0.9;
        g.beginPath(); g.arc(it.cx, it.cy, it.r, 0, Math.PI * 2); g.stroke();
        g.beginPath(); g.moveTo(it.cx - it.r * 1.8, it.cy); g.lineTo(it.cx + it.r * 1.8, it.cy); g.moveTo(it.cx, it.cy - it.r * 1.8); g.lineTo(it.cx, it.cy + it.r * 1.8); g.stroke();
        break;
      case 'sun':
        g.save();
        g.beginPath(); g.arc(it.cx, it.cy, it.r, 0, Math.PI * 2); g.fillStyle = it.fill; g.fill(); g.clip();
        g.fillStyle = it.barFill;
        for (const [y, h] of it.bars) g.fillRect(it.cx - it.r, y, it.r * 2, h);
        g.restore();
        break;
      case 'dots': {
        g.fillStyle = it.fill;
        const cols = Math.floor(it.w / it.step), rows = Math.max(1, Math.floor(it.h / it.step));
        for (let i = 0; i <= cols; i++) {
          const r = it.r0 + (it.r1 - it.r0) * (i / Math.max(1, cols));
          for (let j = 0; j < rows; j++) { g.beginPath(); g.arc(it.x + i * it.step, it.y + (j + 0.5) * (it.h / rows), r, 0, Math.PI * 2); g.fill(); }
        }
        break;
      }
      case 'text':
        g.font = fontOf(it);
        g.fillStyle = it.fill;
        g.textAlign = it.align;
        g.textBaseline = 'alphabetic';
        if (tracked) (g as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = `${it.tracking * it.size}px`;
        g.fillText(it.text, it.x, it.y);
        break;
    }
  }
  if (tracked) (g as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = '0px';
  g.restore();
}

/**
 * Lens state and physics, independent of the renderer: the WebGL scene and the CSS fallback both drive `step()` from
 * their own frame loop and read `frame()`. Coordinates are CSS pixels inside the stage, y pointing down.
 *
 * - Drag tracks the pointer 1:1 (rubber-banded past the edges); release keeps the pointer's velocity and glides with
 *   friction; past an edge a `spring.release` pulls the lens back, so a throw bounces gently instead of stopping dead.
 * - Keyboard steps, "centre" and click-to-place seek with springs that keep the current velocity.
 * - Speed stretches the glass along its motion (area-preserving, `spring.pop`), so it wobbles when it stops.
 * - One light direction for the whole scene, eased with `spring.glide` toward the pointer.
 * Reduced motion: positions, shape and lift jump; no glide, rubber band, stretch or light animation.
 */
import { duration, sec, spring, type SpringConfig } from '../../motion';

export type ShapeId = 'pill' | 'circle' | 'squircle';
export const SHAPE_IDS: readonly ShapeId[] = ['pill', 'circle', 'squircle'];

/** SDF parameters in units of the lens radius: half extents, corner radius, corner exponent (2 round, >2 squircle). */
export const SHAPES: Record<ShapeId, { hx: number; hy: number; r: number; n: number }> = {
  pill: { hx: 1.62, hy: 0.8, r: 0.8, n: 2 },
  circle: { hx: 1, hy: 1, r: 1, n: 2 },
  squircle: { hx: 1.01, hy: 1.01, r: 1.01, n: 4.4 },
};

interface Spring1 { x: number; v: number; to: number }
const make = (x: number): Spring1 => ({ x, v: 0, to: x });
const SUB = 1 / 240; // fixed sub-step: semi-implicit Euler stays stable for the stiffest token at any frame time
function advance(s: Spring1, c: SpringConfig, dt: number): void {
  for (let t = 0; t < dt; t += SUB) {
    const h = Math.min(SUB, dt - t);
    s.v += ((-c.stiffness * (s.x - s.to) - c.damping * s.v) / c.mass) * h;
    s.x += s.v * h;
  }
}
const still = (s: Spring1, eps: number) => Math.abs(s.x - s.to) < eps && Math.abs(s.v) < eps * 8;
const snap = (s: Spring1, x = s.to) => { s.x = x; s.to = x; s.v = 0; };
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const smooth = (a: number, b: number, x: number) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
/** iOS-style resistance: the further past the edge, the less the lens follows. */
const band = (over: number, d: number) => (1 - 1 / ((over * 0.55) / d + 1)) * d;

/** Velocity decays with this time constant while gliding (throw distance ≈ speed × GLIDE). */
const GLIDE = sec(duration.moderate);
const MAX_SPEED = 3600;
const STRETCH_MAX = 0.085;
const MARGIN = 10;
const DEG = Math.PI / 180;
/** Resting light: from the upper left, 38° above the page. */
const REST_AZ: [number, number] = [-0.6, -0.8];
const REST_EL = 38 * DEG;
const lightVec = (az: [number, number], el: number): [number, number, number] => [az[0] * Math.cos(el), az[1] * Math.cos(el), Math.sin(el)];

export interface LensFrame {
  /** centre */ x: number; y: number;
  /** half extents and corner radius (px) and corner exponent, lift scale applied */ hx: number; hy: number; r: number; n: number;
  /** stretch amount (+ along dir, − squash) and its unit direction */ stretch: number; dirX: number; dirY: number;
  /** 0 resting, 0.35 hovered, 1 held */ lift: number;
  /** unit vector toward the light (x right, y down, z toward the viewer) */ lx: number; ly: number; lz: number;
}

export class LensEngine {
  w = 0;
  h = 0;
  /** Base radius of the lens (px), from the stage size. */
  R = 80;
  reduced = false;
  follow = true;
  private x = make(0);
  private y = make(0);
  private mode: 'rest' | 'drag' | 'glide' | 'seek' = 'rest';
  private seekCfg: SpringConfig = spring.settle;
  private placed = false;
  private grab = { x: 0, y: 0 };
  private raw = { x: 0, y: 0 };
  private samples: { t: number; x: number; y: number }[] = [];
  private shape = { hx: make(SHAPES.pill.hx), hy: make(SHAPES.pill.hy), r: make(SHAPES.pill.r), n: make(SHAPES.pill.n) };
  private stretch = make(0);
  private dir = { x: 1, y: 0 };
  private lift = make(0);
  private hovered = false;
  private pointer = { x: 0, y: 0, inside: false };
  private az: [number, number] = [...REST_AZ];
  private light = { x: make(lightVec(REST_AZ, REST_EL)[0]), y: make(lightVec(REST_AZ, REST_EL)[1]), z: make(lightVec(REST_AZ, REST_EL)[2]) };

  get dragging(): boolean { return this.mode === 'drag'; }

  /** Stage size. The first call places the lens; later calls keep its relative position. */
  setSize(w: number, h: number): void {
    if (w <= 0 || h <= 0) return;
    this.R = clamp(Math.min(w, h) * 0.2, 40, 132);
    if (!this.placed) {
      this.placed = true;
      // Resting spot: across the display word and the edge of the sun, where there is most to bend.
      snap(this.x, w * 0.56);
      snap(this.y, h * 0.6);
    } else if (this.w > 0 && this.h > 0) {
      const sx = w / this.w, sy = h / this.h;
      for (const [s, k] of [[this.x, sx], [this.y, sy]] as const) { s.x *= k; s.to *= k; }
      this.raw.x *= sx; this.raw.y *= sy;
    }
    this.w = w;
    this.h = h;
    const [lx, hx, ly, hy] = this.bounds();
    if (this.mode === 'rest') { snap(this.x, clamp(this.x.x, lx, hx)); snap(this.y, clamp(this.y.x, ly, hy)); }
  }

  setShape(id: ShapeId, instant = false): void {
    const t = SHAPES[id];
    for (const k of ['hx', 'hy', 'r', 'n'] as const) {
      this.shape[k].to = t[k];
      if (instant || this.reduced) snap(this.shape[k]);
    }
  }

  /** Lens centre limits for the target shape. */
  private bounds(): [number, number, number, number] {
    const hx = this.shape.hx.to * this.R + MARGIN, hy = this.shape.hy.to * this.R + MARGIN;
    const lx = Math.min(hx, this.w / 2), ly = Math.min(hy, this.h / 2);
    return [lx, Math.max(lx, this.w - hx), ly, Math.max(ly, this.h - hy)];
  }

  /** True when (px, py) falls on the lens (its current, unstretched shape). */
  hit(px: number, py: number): boolean {
    const f = this.frame();
    const qx = Math.abs(px - f.x) - f.hx + f.r, qy = Math.abs(py - f.y) - f.hy + f.r;
    const ox = Math.max(qx, 0), oy = Math.max(qy, 0);
    return Math.min(Math.max(qx, qy), 0) + Math.hypot(ox, oy) - f.r <= 0;
  }

  pointerMove(px: number, py: number, inside = true): void {
    this.pointer = { x: px, y: py, inside };
    if (this.mode === 'drag') {
      this.raw = { x: px, y: py };
      const t = performance.now();
      this.samples.push({ t, x: px, y: py });
      while (this.samples.length > 8 || (this.samples.length > 2 && t - this.samples[0].t > 160)) this.samples.shift();
    }
  }
  pointerLeave(): void { this.pointer = { ...this.pointer, inside: false }; }
  setHover(on: boolean): void { this.hovered = on; }

  dragStart(px: number, py: number): void {
    this.mode = 'drag';
    this.grab = { x: px - this.x.x, y: py - this.y.x };
    this.raw = { x: px, y: py };
    this.samples = [{ t: performance.now(), x: px, y: py }];
    this.pointer = { x: px, y: py, inside: true };
  }

  dragEnd(): void {
    if (this.mode !== 'drag') return;
    const [vx, vy] = this.pointerVelocity(performance.now());
    const speed = Math.hypot(vx, vy);
    const k = speed > MAX_SPEED ? MAX_SPEED / speed : 1;
    this.samples = [];
    if (this.reduced) { this.mode = 'rest'; this.x.v = this.y.v = 0; return; }
    this.x.v = vx * k;
    this.y.v = vy * k;
    this.mode = 'glide';
  }

  /** Move by (dx, dy): keyboard steps accumulate on the running target, so held keys stay smooth. */
  nudge(dx: number, dy: number): void {
    const [lx, hx, ly, hy] = this.bounds();
    const bx = this.mode === 'seek' ? this.x.to : this.x.x, by = this.mode === 'seek' ? this.y.to : this.y.x;
    this.seek(clamp(bx + dx, lx, hx), clamp(by + dy, ly, hy), spring.settle);
  }
  recentre(): void { this.seek(this.w / 2, this.h / 2, spring.glide); }
  /** Send the lens to a point (clamped inside the stage). */
  placeAt(px: number, py: number): void {
    const [lx, hx, ly, hy] = this.bounds();
    this.seek(clamp(px, lx, hx), clamp(py, ly, hy), spring.glide);
  }
  private seek(tx: number, ty: number, cfg: SpringConfig): void {
    if (this.reduced) { snap(this.x, tx); snap(this.y, ty); this.mode = 'rest'; return; }
    this.x.to = tx;
    this.y.to = ty;
    this.seekCfg = cfg;
    this.mode = 'seek';
  }

  /** Position as a fraction of the stage, for announcements. */
  where(): { fx: number; fy: number } {
    return { fx: this.w ? this.x.to / this.w : 0.5, fy: this.h ? this.y.to / this.h : 0.5 };
  }

  private pointerVelocity(now: number): [number, number] {
    const s = this.samples;
    if (s.length < 2) return [0, 0];
    const last = s[s.length - 1];
    if (now - last.t > 70) return [0, 0]; // the pointer stopped before letting go
    let i = s.length - 1;
    while (i > 0 && last.t - s[i - 1].t <= 100) i--;
    const first = s[i];
    const dt = (last.t - first.t) / 1000;
    return dt < 0.008 ? [0, 0] : [(last.x - first.x) / dt, (last.y - first.y) / dt];
  }

  /** Advance by dt seconds. Returns true while another frame is needed. */
  step(rawDt: number): boolean {
    const dt = clamp(rawDt, 0, 1 / 20);
    const now = performance.now();
    const [lx, hx, ly, hy] = this.bounds();
    let vx = 0, vy = 0;
    let busy = false;

    if (this.mode === 'drag') {
      const tx = this.raw.x - this.grab.x, ty = this.raw.y - this.grab.y;
      const px = this.x.x, py = this.y.x;
      if (this.reduced) { this.x.x = clamp(tx, lx, hx); this.y.x = clamp(ty, ly, hy); }
      else {
        const d = this.R * 1.2;
        this.x.x = tx < lx ? lx - band(lx - tx, d) : tx > hx ? hx + band(tx - hx, d) : tx;
        this.y.x = ty < ly ? ly - band(ly - ty, d) : ty > hy ? hy + band(ty - hy, d) : ty;
      }
      this.x.to = this.x.x;
      this.y.to = this.y.x;
      [vx, vy] = this.pointerVelocity(now);
      busy = px !== this.x.x || py !== this.y.x || vx !== 0 || vy !== 0;
    } else if (this.mode === 'glide') {
      this.glideAxis(this.x, lx, hx, dt);
      this.glideAxis(this.y, ly, hy, dt);
      vx = this.x.v; vy = this.y.v;
      const inside = this.x.x >= lx - 0.5 && this.x.x <= hx + 0.5 && this.y.x >= ly - 0.5 && this.y.x <= hy + 0.5;
      if (inside && Math.hypot(vx, vy) < 6) {
        snap(this.x, clamp(this.x.x, lx, hx));
        snap(this.y, clamp(this.y.x, ly, hy));
        this.mode = 'rest';
      } else busy = true;
    } else if (this.mode === 'seek') {
      advance(this.x, this.seekCfg, dt);
      advance(this.y, this.seekCfg, dt);
      vx = this.x.v; vy = this.y.v;
      if (still(this.x, 0.05) && still(this.y, 0.05)) { snap(this.x); snap(this.y); this.mode = 'rest'; } else busy = true;
    } else if (this.x.x < lx - 0.5 || this.x.x > hx + 0.5 || this.y.x < ly - 0.5 || this.y.x > hy + 0.5) {
      // A morph to a wider shape (or a resize) pushed the lens past an edge: slide it back in.
      this.seek(clamp(this.x.x, lx, hx), clamp(this.y.x, ly, hy), spring.settle);
      busy = true;
    }

    // Shape morph: a slightly under-damped spring, so the glass settles like a liquid.
    for (const k of ['hx', 'hy', 'r', 'n'] as const) {
      const s = this.shape[k];
      if (this.reduced) snap(s); else { advance(s, spring.release, dt); if (still(s, 0.0005)) snap(s); else busy = true; }
    }

    // Squash and stretch along the motion.
    const speed = Math.hypot(vx, vy);
    if (this.reduced) snap(this.stretch, 0);
    else {
      if (speed > 30) {
        let nx = vx / speed, ny = vy / speed;
        if (nx * this.dir.x + ny * this.dir.y < 0) { nx = -nx; ny = -ny; } // a stretch has no front: never flip
        const k = 1 - Math.exp(-dt * 18);
        const dx = this.dir.x + (nx - this.dir.x) * k, dy = this.dir.y + (ny - this.dir.y) * k;
        const l = Math.hypot(dx, dy) || 1;
        this.dir = { x: dx / l, y: dy / l };
      }
      this.stretch.to = Math.min(speed / 2600, 1) * STRETCH_MAX;
      advance(this.stretch, spring.pop, dt);
      if (still(this.stretch, 0.0004)) snap(this.stretch); else busy = true;
    }

    // Lift: held glass rises (its shadow grows and softens), hovered glass rises a little.
    this.lift.to = this.mode === 'drag' ? 1 : this.hovered ? 0.35 : 0;
    if (this.reduced) snap(this.lift); else { advance(this.lift, spring.settle, dt); if (still(this.lift, 0.002)) snap(this.lift); else busy = true; }

    // One light for the scene: toward the pointer when it follows, else the resting upper-left light.
    let target = lightVec(REST_AZ, REST_EL);
    if (this.follow && !this.reduced && this.pointer.inside) {
      const dx = this.pointer.x - this.x.x, dy = this.pointer.y - this.y.x;
      const dist = Math.hypot(dx, dy);
      if (dist > this.R * 0.45) this.az = [dx / dist, dy / dist]; // close to the centre the azimuth is noise: keep it
      target = lightVec(this.az, (56 - 30 * smooth(this.R * 0.6, this.R * 5, dist)) * DEG);
    }
    const L = this.light;
    L.x.to = target[0]; L.y.to = target[1]; L.z.to = target[2];
    for (const s of [L.x, L.y, L.z]) {
      if (this.reduced) snap(s); else { advance(s, spring.glide, dt); if (still(s, 0.001)) snap(s); else busy = true; }
    }
    return busy;
  }

  private glideAxis(s: Spring1, lo: number, hi: number, dt: number): void {
    const c = spring.release;
    for (let t = 0; t < dt; t += SUB) {
      const h = Math.min(SUB, dt - t);
      const edge = s.x < lo ? lo : s.x > hi ? hi : null;
      if (edge === null) s.v *= Math.exp(-h / GLIDE);
      else s.v += ((-c.stiffness * (s.x - edge) - c.damping * s.v) / c.mass) * h;
      s.x += s.v * h;
    }
    s.to = s.x;
  }

  frame(): LensFrame {
    const k = this.R * (1 + 0.03 * this.lift.x);
    const hx = Math.max(0.05, this.shape.hx.x) * k, hy = Math.max(0.05, this.shape.hy.x) * k;
    const L = this.light;
    const l = Math.hypot(L.x.x, L.y.x, L.z.x) || 1;
    return {
      x: this.x.x, y: this.y.x, hx, hy, r: Math.min(Math.max(0, this.shape.r.x * k), hx, hy), n: Math.max(1.5, this.shape.n.x),
      stretch: this.stretch.x, dirX: this.dir.x, dirY: this.dir.y, lift: this.lift.x,
      lx: L.x.x / l, ly: L.y.x / l, lz: L.z.x / l,
    };
  }
}

'use client';
/**
 * No-WebGL path. `PageSvg` draws the same composition as the WebGL texture, as SVG in the DOM; `GlassFallback` runs
 * the lens physics on a rAF loop (instead of the R3F frame loop) and tells the host to dress the lens handle as a
 * CSS glass panel (backdrop-filter, layered rims, a sheen that follows the light).
 */
import { useEffect, useId, useMemo, useRef, useState, type ReactNode, type RefObject } from 'react';
import { useElementSize, useRafLoop } from '../../motion';
import { canvasMeasure, compose, type Theme } from './composition';
import type { LensEngine } from './engine';
import styles from './styles.module.css';

export function PageSvg({ theme }: { theme: Theme | null }) {
  const box = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(box);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '');
  const comp = useMemo(() => (theme && width > 0 && height > 0 ? compose(width / height, theme, canvasMeasure()) : null), [theme, width, height]);
  return (
    <div ref={box} className={styles.page} aria-hidden="true">
      {comp ? (
        <svg viewBox={`0 0 ${comp.width} ${comp.height}`} preserveAspectRatio="xMidYMid slice" focusable="false">
          {comp.items.map((it, i) => {
            switch (it.k) {
              case 'rect': return <rect key={i} x={it.x} y={it.y} width={it.w} height={it.h} fill={it.fill} />;
              case 'grid': {
                const lines: ReactNode[] = [];
                for (let j = 0, x = 0; x <= it.w; x += it.step, j++) lines.push(<line key={`v${j}`} x1={x} y1={0} x2={x} y2={it.h} stroke={j % it.every ? it.minor : it.major} />);
                for (let j = 0, y = 0; y <= it.h; y += it.step, j++) lines.push(<line key={`h${j}`} x1={0} y1={y} x2={it.w} y2={y} stroke={j % it.every ? it.minor : it.major} />);
                return <g key={i} strokeWidth={1} vectorEffect="non-scaling-stroke">{lines}</g>;
              }
              case 'line': return <line key={i} x1={it.x1} y1={it.y1} x2={it.x2} y2={it.y2} stroke={it.stroke} strokeWidth={it.width} />;
              case 'reg': return (
                <g key={i} fill="none" stroke={it.stroke} strokeWidth={0.9}>
                  <circle cx={it.cx} cy={it.cy} r={it.r} />
                  <path d={`M${it.cx - it.r * 1.8} ${it.cy}H${it.cx + it.r * 1.8}M${it.cx} ${it.cy - it.r * 1.8}V${it.cy + it.r * 1.8}`} />
                </g>
              );
              case 'sun': return (
                <g key={i}>
                  <clipPath id={`${uid}sun${i}`}><circle cx={it.cx} cy={it.cy} r={it.r} /></clipPath>
                  <circle cx={it.cx} cy={it.cy} r={it.r} fill={it.fill} />
                  <g clipPath={`url(#${uid}sun${i})`} fill={it.barFill}>
                    {it.bars.map(([y, h], j) => <rect key={j} x={it.cx - it.r} y={y} width={it.r * 2} height={h} />)}
                  </g>
                </g>
              );
              case 'dots': {
                const cols = Math.floor(it.w / it.step), rows = Math.max(1, Math.floor(it.h / it.step));
                const dots: ReactNode[] = [];
                for (let a = 0; a <= cols; a++) for (let b = 0; b < rows; b++) {
                  dots.push(<circle key={`${a}-${b}`} cx={it.x + a * it.step} cy={it.y + (b + 0.5) * (it.h / rows)} r={it.r0 + (it.r1 - it.r0) * (a / Math.max(1, cols))} />);
                }
                return <g key={i} fill={it.fill}>{dots}</g>;
              }
              case 'text': return (
                <text
                  key={i} x={it.x} y={it.y} fill={it.fill} fontFamily={it.family} fontSize={it.size} fontWeight={it.weight}
                  fontStyle={it.italic ? 'italic' : undefined} letterSpacing={it.tracking * it.size}
                  textAnchor={it.align === 'left' ? 'start' : it.align === 'right' ? 'end' : 'middle'}
                >{it.text}</text>
              );
            }
          })}
        </svg>
      ) : null}
    </div>
  );
}

export interface GlassFallbackProps {
  engine: LensEngine;
  wake: RefObject<(() => void) | null>;
  onFrame: RefObject<(() => void) | null>;
  /** Mounted (true) / unmounted (false): the host switches the lens handle to its CSS glass dress. */
  onActive: (active: boolean) => void;
  children: ReactNode;
}

export function GlassFallback({ engine, wake, onFrame, onActive, children }: GlassFallbackProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [running, setRunning] = useState(true);
  useEffect(() => {
    const start = () => setRunning(true);
    wake.current = start;
    onActive(true);
    return () => { if (wake.current === start) wake.current = null; onActive(false); };
  }, [wake, onActive]);
  useRafLoop(ref, (dt) => {
    const busy = engine.step(dt);
    onFrame.current?.();
    if (!busy) setRunning(false);
  }, running);
  return <div ref={ref} className={styles.page}>{children}</div>;
}

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef, useState, type RefObject } from 'react';
import {
  CanvasTexture, ClampToEdgeWrapping, Color, LinearFilter, LinearMipmapLinearFilter, ShaderMaterial, SRGBColorSpace, Vector2, Vector3, Vector4,
} from 'three';
import { useQuality } from '../../three';
import type { LensEngine } from './engine';
import { fragmentShader, vertexShader } from './shader';

/** Glass look per theme (sRGB hex; three converts to linear). */
export interface GlassLook { dark: boolean; envLo: string; envHi: string; light: string; shadow: string; shadowAmount: number; caustic: number }

export interface SceneProps {
  engine: LensEngine;
  /** Draws the page in CSS pixels into a context already scaled to the drawing buffer. */
  draw: RefObject<(g: CanvasRenderingContext2D, width: number, height: number) => void>;
  /** Redraw the page texture when this changes (theme, fonts, content). */
  drawKey: unknown;
  refraction: number;
  dispersion: number;
  frost: number;
  look: GlassLook;
  /** The active frame driver: wakes the render loop. */
  wake: RefObject<(() => void) | null>;
  /** Called after each simulated frame so DOM overlays follow the lens in the same frame. */
  onFrame: RefObject<(() => void) | null>;
}

const SAMPLES = { high: 12, medium: 9, low: 6 } as const;

export function Scene({ engine, draw, drawKey, refraction, dispersion, frost, look, wake, onFrame }: SceneProps) {
  const gl = useThree((s) => s.gl);
  const size = useThree((s) => s.size);
  const dpr = useThree((s) => s.viewport.dpr);
  const invalidate = useThree((s) => s.invalidate);
  const quality = useQuality();
  const buffer = useRef(new Vector2());

  // Page texture at drawing-buffer resolution (already capped by the quality profile's DPR). Resizes are debounced so
  // a window drag does not redraw and re-upload on every frame; the old texture stretches for the moment in between.
  const [texSize, setTexSize] = useState<[number, number] | null>(null);
  useEffect(() => {
    const max = gl.capabilities.maxTextureSize || 4096;
    const next: [number, number] = [Math.min(max, Math.round(size.width * dpr)), Math.min(max, Math.round(size.height * dpr))];
    if (next[0] < 2 || next[1] < 2) return;
    const id = window.setTimeout(() => setTexSize((s) => (s && s[0] === next[0] && s[1] === next[1] ? s : next)), texSize ? 140 : 0);
    return () => window.clearTimeout(id);
  }, [size.width, size.height, dpr, gl, texSize]);

  const texture = useMemo(() => {
    if (!texSize) return null;
    const c = document.createElement('canvas');
    c.width = texSize[0];
    c.height = texSize[1];
    const g = c.getContext('2d');
    if (!g) return null;
    const cssW = texSize[0] / dpr, cssH = texSize[1] / dpr;
    g.setTransform(texSize[0] / cssW, 0, 0, texSize[1] / cssH, 0, 0);
    draw.current?.(g, cssW, cssH);
    const t = new CanvasTexture(c);
    t.colorSpace = SRGBColorSpace;
    t.generateMipmaps = true; // the frost and the compressed rim sample blurrier levels with textureLod
    t.minFilter = LinearMipmapLinearFilter;
    t.magFilter = LinearFilter;
    t.wrapS = t.wrapT = ClampToEdgeWrapping;
    return t;
    // drawKey is the redraw trigger for content drawn through the `draw` ref
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [texSize, drawKey]);
  useEffect(() => () => { texture?.dispose(); }, [texture]);

  const uniforms = useMemo(() => ({
    uPage: { value: null as CanvasTexture | null }, uRes: { value: new Vector2(1, 1) }, uDpr: { value: 1 },
    uCenter: { value: new Vector2() }, uShape: { value: new Vector4(80, 40, 40, 2) }, uStretch: { value: new Vector3(1, 0, 0) },
    uLight: { value: new Vector3(-0.5, 0.6, 0.6) }, uLift: { value: 6 }, uRefract: { value: 1 }, uDisperse: { value: 0.5 }, uFrost: { value: 0 },
    uMaxLod: { value: 8 }, uEnvLo: { value: new Color() }, uEnvHi: { value: new Color() }, uLightColor: { value: new Color() },
    uShadowColor: { value: new Color() }, uShadow: { value: 0.3 }, uCaustic: { value: 0.2 }, uDark: { value: 0 },
  }), []);

  // Built imperatively: R3F copies uniform objects passed as JSX props, so later writes would not reach the material.
  const samples = SAMPLES[quality.level];
  const material = useMemo(() => new ShaderMaterial({
    uniforms, vertexShader, fragmentShader, defines: { SAMPLES: samples }, depthTest: false, depthWrite: false,
  }), [uniforms, samples]);
  useEffect(() => () => material.dispose(), [material]);

  useEffect(() => {
    uniforms.uPage.value = texture;
    if (texture) uniforms.uMaxLod.value = Math.floor(Math.log2(Math.max(texture.image.width, texture.image.height)));
    invalidate();
  }, [texture, uniforms, invalidate]);

  useEffect(() => {
    const u = uniforms;
    u.uRefract.value = refraction; u.uDisperse.value = dispersion; u.uFrost.value = frost;
    u.uEnvLo.value.set(look.envLo); u.uEnvHi.value.set(look.envHi); u.uLightColor.value.set(look.light); u.uShadowColor.value.set(look.shadow);
    u.uShadow.value = look.shadowAmount; u.uCaustic.value = look.caustic; u.uDark.value = look.dark ? 1 : 0;
    invalidate();
  }, [refraction, dispersion, frost, look, uniforms, invalidate]);

  useEffect(() => {
    wake.current = invalidate;
    invalidate();
    return () => { if (wake.current === invalidate) wake.current = null; };
  }, [wake, invalidate]);

  useFrame((state, dt) => {
    const busy = engine.step(dt);
    onFrame.current?.();
    state.gl.getDrawingBufferSize(buffer.current);
    const bw = buffer.current.x, bh = buffer.current.y;
    const k = bw / Math.max(1, state.size.width);
    const f = engine.frame();
    const u = uniforms;
    u.uRes.value.set(bw, bh);
    u.uDpr.value = k;
    u.uCenter.value.set(f.x * k, bh - f.y * k);
    u.uShape.value.set(f.hx * k, f.hy * k, f.r * k, f.n);
    u.uStretch.value.set(f.dirX, -f.dirY, f.stretch);
    u.uLight.value.set(f.lx, -f.ly, f.lz);
    u.uLift.value = (8 + 18 * f.lift) * k; // resting on a thin cushion of air; held glass rises
    if (busy) invalidate();
  });

  if (!texture) return null;
  return (
    <mesh frustumCulled={false} material={material}>
      <planeGeometry args={[2, 2]} />
    </mesh>
  );
}

/**
 * Liquid glass over a page texture, in one full-frame pass.
 *
 * The lens is a signed distance field (a rounded box whose corners are superellipse arcs: pill, circle and squircle
 * are parameter sets of the same function). Inside it, the distance to the edge drives a convex bezel profile: the top
 * is flat in the middle and curves down to the rim, so its normal is vertical at the centre and tips outward at the
 * edge. The view ray is refracted through that surface and through the flat underside (Snell, per wavelength), so the
 * centre shows the page untouched and the rim gathers and splits it into colour. Fresnel mixes in a studio reflection,
 * a Blinn–Phong highlight answers the one scene light, and the glass casts a light shadow with a caustic away from it.
 * Coordinates are drawing-buffer pixels with the origin at the bottom left (gl_FragCoord).
 */
export const vertexShader = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0); // clip-space quad
}`;

export const fragmentShader = /* glsl */ `
precision highp float;

uniform sampler2D uPage;
uniform vec2 uRes;        // drawing buffer size (px)
uniform float uDpr;       // drawing-buffer px per CSS px
uniform vec2 uCenter;     // lens centre (px)
uniform vec4 uShape;      // half width, half height, corner radius (px), corner exponent
uniform vec3 uStretch;    // unit direction, amount (> 0 stretch along it, < 0 squash)
uniform vec3 uLight;      // unit vector toward the light (x right, y up, z toward the viewer)
uniform float uLift;      // height of the glass above the page (px)
uniform float uRefract;   // 0 … 1.5
uniform float uDisperse;  // 0 … 1
uniform float uFrost;     // 0 … 1
uniform float uMaxLod;
uniform vec3 uEnvLo;      // studio reflection at grazing angles (the walls)
uniform vec3 uEnvHi;      // … and straight up (the ceiling); the light adds its own lobe
uniform vec3 uLightColor;
uniform vec3 uShadowColor;
uniform float uShadow;    // shadow density on this page colour
uniform float uCaustic;   // focused light inside the shadow
uniform float uDark;

varying vec2 vUv;

#ifndef SAMPLES
#define SAMPLES 8
#endif

float lpLength(vec2 v, float n) {
  v = abs(v);
  float m = max(v.x, v.y);
  if (m <= 0.0) return 0.0;
  v /= m;
  return m * pow(pow(v.x, n) + pow(v.y, n), 1.0 / n);
}

// Rounded box with superellipse corners; exact for the pill and circle (n = 2), close for the squircle.
float sdLens(vec2 p) {
  vec2 b = uShape.xy;
  float r = min(uShape.z, min(b.x, b.y));
  vec2 q = abs(p) - b + r;
  return min(max(q.x, q.y), 0.0) + lpLength(max(q, 0.0), uShape.w) - r;
}

// Squash and stretch along the motion, area-preserving: evaluate the field in the un-stretched frame.
vec2 lensSpace(vec2 frag, vec2 centre) {
  vec2 p = frag - centre;
  float s = 1.0 + uStretch.z;
  float a = dot(p, uStretch.xy);
  return uStretch.xy * (a / s) + (p - uStretch.xy * a) * s;
}

// x: Euclidean-corrected signed distance (px), yz: outward unit normal of the outline.
vec3 field(vec2 frag) {
  float d = sdLens(lensSpace(frag, uCenter));
  const float e = 0.75;
  vec2 g = vec2(
    sdLens(lensSpace(frag + vec2(e, 0.0), uCenter)) - sdLens(lensSpace(frag - vec2(e, 0.0), uCenter)),
    sdLens(lensSpace(frag + vec2(0.0, e), uCenter)) - sdLens(lensSpace(frag - vec2(0.0, e), uCenter))
  ) / (2.0 * e);
  float gl = max(length(g), 1e-4);
  return vec3(d / gl, g / gl);
}

vec3 page(vec2 px, float lod) {
  return textureLod(uPage, clamp(px / uRes, vec2(0.0), vec2(1.0)), lod).rgb;
}

// Smooth spectral weights from the red end (c = 0) to the blue end (c = 1); normalised per channel later.
vec3 spectrum(float c) {
  return clamp(vec3(1.4 - abs(c - 0.12) * 3.2, 1.0 - abs(c - 0.5) * 2.6, 1.4 - abs(c - 0.88) * 3.2), 0.0, 1.0);
}

float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

// Shadow of the glass on the page, cast away from the light. Light through the flat middle goes straight down, so
// only a band under the bezel darkens (its light was bent inward) and a caustic ring forms where that light lands;
// a wide, faint occlusion grows with the lift. Returns (darkening, caustic).
vec2 shadowAt(vec2 px, float rim) {
  vec2 off = -uLight.xy / max(uLight.z, 0.3) * uLift;
  float ds = sdLens(lensSpace(px, uCenter + off));
  float soft = 1.5 * uDpr + uLift * 0.45;
  float foot = 1.0 - smoothstep(-soft, soft * 1.5, ds);
  float band = smoothstep(-rim * 0.95, -rim * 0.05, ds);
  // Occlusion only around the footprint: glass transmits, so the page under it is not occluded.
  float wide = (1.0 - smoothstep(-rim * 0.5, rim * 0.7 + uLift * 2.4, ds)) * smoothstep(-rim * 0.45, rim * 0.15, ds) * 0.3;
  float dark = max(foot * band * 0.9, wide) * uShadow;
  float ring = foot * exp(-pow((ds + rim * 0.68) / (rim * 0.12 + uDpr), 2.0)) * uCaustic;  // irradiance gain
  return vec2(dark, ring);
}

// Light added like a screen: it brightens toward white but never clips, and leaves the page itself untouched.
vec3 addLight(vec3 c, vec3 light) { return 1.0 - (1.0 - c) * exp(-light); }

// Shadow and caustic change the light falling on the page, so both scale its colour (black ink stays black).
vec3 shadePage(vec3 c, vec2 px, float rim) {
  vec2 s = shadowAt(px, rim);
  return c * mix(vec3(1.0), uShadowColor, s.x) * (1.0 + uLightColor * s.y);
}

void main() {
  vec2 frag = gl_FragCoord.xy;
  float rim = 0.46 * min(uShape.x, uShape.y);
  vec3 base = page(frag, 0.0);

  // Far from the lens and its shadow: just the page.
  float reach = max(uShape.x, uShape.y) * (1.0 + abs(uStretch.z)) + uLift * 3.5 + rim + 8.0 * uDpr;
  vec2 rel = frag - uCenter;
  if (dot(rel, rel) > reach * reach) {
    gl_FragColor = vec4(base, 1.0);
    #include <colorspace_fragment>
    return;
  }

  vec3 f = field(frag);
  float d = f.x;
  vec2 g = f.yz;
  vec3 outside = shadePage(base, frag, rim);
  if (d > 1.5) {
    gl_FragColor = vec4(outside, 1.0);
    #include <colorspace_fragment>
    return;
  }

  // Bezel profile: h(u) = (1 - (1 - u)^p)^(1/p), u = 0 at the rim, 1 where the flat top begins.
  float t = max(-d, 0.0);
  float u = clamp(t / rim, 0.0, 1.0);
  const float P = 2.6;
  float k = 1.0 - u;
  float h = pow(max(1.0 - pow(k, P), 1e-4), 1.0 / P);
  float rimH = rim * 0.85;
  float slope = min(pow(k, P - 1.0) * pow(h, 1.0 - P) * (rimH / rim), 14.0);
  vec3 N = normalize(vec3(g * slope, 1.0));
  vec3 I = vec3(0.0, 0.0, -1.0);
  float thick = rimH * (0.4 + h);           // flat slab under a domed bezel
  float gap = uLift;

  float ior = 1.0 + 0.5 * uRefract;
  float blurR = uFrost * 13.0 * uDpr;
  float lod = clamp(log2(1.0 + blurR * 0.45) + 0.9 * (1.0 - u) * smoothstep(1.0, 8.0, slope), 0.0, uMaxLod);
  float rot = 6.2831853 * ign(frag);

  vec3 acc = vec3(0.0);
  vec3 wsum = vec3(0.0);
  vec2 offG = vec2(0.0);
  for (int i = 0; i < SAMPLES; i++) {
    float fi = float(i);
    float c = fract((fi + 0.5) * 0.6180339887);             // wavelength, decorrelated from the frost tap
    float iorC = 1.0 + (ior - 1.0) * (1.0 + uDisperse * 0.62 * (c - 0.5));
    vec3 r1 = refract(I, N, 1.0 / iorC);
    vec2 off = r1.xy / max(-r1.z, 0.2) * thick;
    vec3 r2 = refract(r1, vec3(0.0, 0.0, 1.0), iorC);        // out through the flat underside
    off += dot(r2, r2) > 0.0 ? r2.xy / max(-r2.z, 0.2) * gap : r1.xy * gap * 3.0;
    float a = fi * 2.3999632 + rot;
    vec2 tap = vec2(cos(a), sin(a)) * sqrt((fi + 0.5) / float(SAMPLES)) * blurR;
    vec3 w = spectrum(c);
    acc += page(frag + off + tap, lod) * w;
    wsum += w;
    offG += off;
  }
  vec3 seen = acc / max(wsum, vec3(1e-4));
  offG /= float(SAMPLES);
  // The page seen through the glass carries the glass's own shadow and caustic.
  vec2 sh = shadowAt(frag + offG, rim);
  seen *= mix(vec3(1.0), uShadowColor, sh.x * 0.85) * (1.0 + uLightColor * sh.y);

  // Absorption: a faint cool tint, a touch stronger along the slanted paths through the bezel.
  seen *= exp(-vec3(0.05, 0.016, 0.01) * (thick / max(rimH, 1.0)) * (0.35 + 0.65 * (1.0 - u)));
  // Frost scatters a little light back toward the viewer.
  seen = mix(seen, uEnvHi * mix(0.92, 0.35, uDark), uFrost * 0.09);

  // Fresnel reflection of a soft studio: the bright room above at normal incidence, darker walls at grazing angles,
  // brighter again toward the light.
  vec3 V = vec3(0.0, 0.0, 1.0);
  float cosI = clamp(N.z, 0.0, 1.0);
  float F = 0.04 + 0.96 * pow(1.0 - cosI, 5.0);
  vec3 R = reflect(I, N);
  float lobe = pow(max(dot(R, uLight), 0.0), 14.0);
  vec3 env = mix(uEnvLo, uEnvHi, smoothstep(0.25, 0.95, R.z)) + uLightColor * lobe * 0.8;
  vec3 col = mix(seen, env, F * 0.92);

  // Highlights from the one light: a crisp glint and a broad sheen on the lit side of the bezel,
  // and the light that crossed the glass catching the far rim.
  vec3 H = normalize(uLight + V);
  float nh = max(dot(N, H), 0.0);
  // Polished glass: the flat top only mirrors the light near the reflection direction, so the broad sheen lives on
  // the curved bezel alone.
  float curve = 1.0 - u;
  float spec = pow(nh, 110.0) * 1.1 + pow(nh, 22.0) * 0.14 * curve;
  vec3 Nb = normalize(vec3(-N.xy, N.z));
  float back = pow(max(dot(Nb, H), 0.0), 80.0) * 0.2 * (1.0 - u) * (1.0 - u);
  vec2 lxy = uLight.xy / max(length(uLight.xy), 1e-4);
  float facing = dot(g, lxy);
  // Edge definition: a bright hairline where the rim meets the light (fading round to the far side), and a thin band
  // of rim light just inside it, as a curved edge catches a soft light.
  float lit = smoothstep(-0.35, 1.0, facing);
  float hair = exp(-t / (1.15 * uDpr));
  float band = exp(-t / (5.0 * uDpr)) * (1.0 - hair);
  col = addLight(col, uLightColor * (spec + hair * (0.3 + 0.9 * lit) * (0.75 + 0.25 * uDark) + band * (0.05 + 0.22 * lit * lit))
    + mix(uLightColor, seen * 1.6 + 0.1, 0.5) * back);
  float inner = exp(-abs(t - 2.4 * uDpr) / (1.2 * uDpr)) * smoothstep(0.35, -0.9, facing);
  col *= 1.0 - inner * mix(0.2, 0.32, uDark);
  // The bezel turned away from the light looks through the glass's own shadow at the darker side of the room.
  col *= 1.0 - smoothstep(0.15, -1.0, facing) * curve * curve * mix(0.09, 0.16, uDark);

  float cover = clamp(0.5 - d / 1.1, 0.0, 1.0);             // ~1px anti-aliased outline
  gl_FragColor = vec4(mix(outside, col, cover), 1.0);
  #include <colorspace_fragment>
}`;

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  align-content: center;
  gap: clamp(10px, 1.8cqi, 16px);
  padding: clamp(10px, 2.4cqi, 22px);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--mk-ink, #11110f);
}

/* The stage. --lx / --ly / --lift are written per frame from the scene's one light, so this shadow, the WebGL glass
   and the CSS glass all fall away from the same light. */
.frame {
  --lx: -0.473;
  --ly: -0.63;
  --lift: 0;
  --shadow-a: 0.3;
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-surface, #fbf9f4);
  box-shadow:
    0 0 0 1px var(--mk-line, #11110f24),
    calc(var(--lx) * -2px) calc(var(--ly) * -2px) 3px rgb(0 0 0 / calc(var(--shadow-a) * 0.35)),
    calc(var(--lx) * -22px) calc(var(--ly) * -22px) 44px -20px rgb(0 0 0 / var(--shadow-a));
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
}
.frame[data-dark] { --shadow-a: 0.7; }
.frame > [data-maquettekit-canvas] { position: absolute !important; inset: 0; min-height: 0 !important; }

/* The lens: hit area, focus ring and keyboard control over the canvas (sized and placed by the engine). */
.lens {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  width: 0;
  height: 0;
  touch-action: none;
  cursor: grab;
  outline: none;
  will-change: transform;
}
.lens:active { cursor: grabbing; }
.lens:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 6px; }

.page { position: absolute; inset: 0; }
.page svg { display: block; width: 100%; height: 100%; }

/* No WebGL: the lens becomes a CSS glass panel over the SVG page. Rims, bezel shade and sheen take the light direction;
   frost, refraction and dispersion map to blur, bezel depth and coloured edge fringes. Clear at frost 0. */
.frame[data-css-glass] .lens {
  --sx: calc(50% + var(--lx) * 42%);
  --sy: calc(50% + var(--ly) * 42%);
  --sheen: rgb(255 255 255 / 0.3);
  --veil: rgb(255 255 255 / 0.08);
  --bezel: rgb(255 255 255 / 0.16);
  --rim-shade: rgb(0 0 0 / 0.12);
  --far: rgb(0 0 0 / 0.07);
  --drop: rgb(0 0 0 / 0.16);
  background:
    radial-gradient(130% 150% at var(--sx) var(--sy), var(--sheen), rgb(255 255 255 / 0.03) 40%, rgb(255 255 255 / 0) 70%),
    linear-gradient(170deg, var(--veil), rgb(255 255 255 / 0) 60%);
  -webkit-backdrop-filter: blur(calc(0.3px + var(--frost, 0) * 12px)) saturate(1.25) contrast(1.06) brightness(1.02);
  backdrop-filter: blur(calc(0.3px + var(--frost, 0) * 12px)) saturate(1.25) contrast(1.06) brightness(1.02);
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.42),
    inset calc(var(--lx) * -1.5px) calc(var(--ly) * -1.5px) 0 0 rgb(255 255 255 / 0.75),
    inset calc(var(--lx) * 1.5px) calc(var(--ly) * 1.5px) 0 0 var(--rim-shade),
    inset 0 0 calc(5px + var(--refract, 1) * 14px) var(--bezel),
    inset calc(var(--lx) * 9px) calc(var(--ly) * 9px) calc(10px + var(--refract, 1) * 10px) -4px var(--far),
    inset calc(1px + var(--disperse, 0.5) * 2.5px) 0 calc(var(--disperse, 0.5) * 5px) calc(var(--disperse, 0.5) * -2px) rgb(255 70 40 / 0.4),
    inset calc(-1px - var(--disperse, 0.5) * 2.5px) 0 calc(var(--disperse, 0.5) * 5px) calc(var(--disperse, 0.5) * -2px) rgb(40 110 255 / 0.4),
    calc(var(--lx) * -3px) calc(var(--ly) * -3px) 4px var(--drop),
    calc(var(--lx) * (-12px - var(--lift) * 16px)) calc(var(--ly) * (-12px - var(--lift) * 16px)) calc(18px + var(--lift) * 22px) var(--drop);
}
.frame[data-css-glass][data-dark] .lens {
  --sheen: rgb(255 255 255 / 0.16);
  --veil: rgb(255 255 255 / 0.04);
  --bezel: rgb(255 255 255 / 0.1);
  --rim-shade: rgb(0 0 0 / 0.4);
  --far: rgb(0 0 0 / 0.22);
  --drop: rgb(0 0 0 / 0.5);
}

/* The kit's "no WebGL" note, set as a small badge so it does not sit over the middle of the page. */
.frame [data-maquettekit-fallback] > p[role='status'] {
  position: absolute;
  left: 10px;
  bottom: 10px;
  z-index: 2;
  max-width: calc(100% - 20px);
  padding: 5px 10px !important;
  border-radius: 999px;
  background: var(--mk-surface, #fbf9f4);
  box-shadow: 0 0 0 1px var(--mk-line, #11110f24);
  font-size: 11.5px !important;
  line-height: 1.35;
  text-align: left !important;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 12px;
}
.shapes {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background: var(--mk-surface-2, #e9e5da);
  box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.1), inset 0 0 0 1px var(--mk-line, #11110f24);
}
.shape,
.centre {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 40px;
  padding: 0 14px 0 11px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink, #11110f);
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: -0.005em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.shape svg,
.centre svg {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
}
.shape[aria-pressed='true'] {
  background: var(--mk-surface, #fbf9f4);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.55),
    0 0 0 1px var(--mk-line, #11110f24),
    0 1px 2px rgb(0 0 0 / 0.14),
    0 6px 14px -8px rgb(0 0 0 / 0.4);
}
.shape[aria-pressed='true'] svg { fill: color-mix(in srgb, currentColor 14%, transparent); }
.centre {
  background: var(--mk-surface, #fbf9f4);
  box-shadow: 0 0 0 1px var(--mk-line, #11110f24), 0 1px 2px rgb(0 0 0 / 0.1);
}
.shape:focus-visible,
.centre:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.hint {
  flex: 1 1 18rem;
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.45;
  color: var(--mk-ink-muted, #5c5a52);
}
.keys { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: -0.01em; }

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (pointer: coarse) {
  .shape, .centre { min-height: 44px; }
}
@container (max-width: 560px) {
  .frame { aspect-ratio: 4 / 5; }
  .shape { padding: 0 12px 0 9px; }
}

@media (prefers-reduced-motion: no-preference) {
  .shape,
  .centre {
    transition:
      background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease),
      box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease),
      transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
  }
  .shape:active,
  .centre:active { transform: scale(0.96); }
}
